@Test
public void testExplodingSequence() {
    final ExplodingSequence<Integer> bomb = new ExplodingSequence<>(Sequences.simple(ImmutableList.of(1, 2, 2)), false, true);
    final CombiningSequence<Integer> combiningSequence = CombiningSequence.create(bomb, Comparator.naturalOrder(), (a, b) -> a);
    try {
        combiningSequence.toYielder(null, new YieldingAccumulator<Integer, Integer>() {

            @Override
            public Integer accumulate(Integer accumulated, Integer in) {
                if (in > 1) {
                    throw new RuntimeException("boom");
                }
                return in;
            }
        });
        Assert.fail("Expected exception");
    } catch (Exception e) {
        Assert.assertThat(e, ThrowableMessageMatcher.hasMessage(CoreMatchers.equalTo("boom")));
    }
    Assert.assertEquals("Closes resources", 1, bomb.getCloseCount());
}

