" + "    }
" + "  }
" + "}";
    final ClassWithMapAndJacksonInject object = new ClassWithMapAndJacksonInject(ImmutableMap.of("foo", "bar", "", "empty"), ImmutableMap.of("foo", new ClassWithJacksonInject("value1", injector.getInstance(InjectedParameter.class)), "", new ClassWithJacksonInject("value2", injector.getInstance(InjectedParameter.class))));
    final String jsonWritten = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(object);
    Assert.assertEquals(expectedSerializedJson, jsonWritten);
    final ClassWithMapAndJacksonInject objectRead = mapper.readValue(json, ClassWithMapAndJacksonInject.class);
