@Test
public void testWithYieldingSequence() {
    // Create a Sequence whose Yielders will yield for each element, regardless of what the accumulator passed
    // to "toYielder" does.
    final BaseSequence<Integer, Iterator<Integer>> sequence = new BaseSequence<Integer, Iterator<Integer>>(new BaseSequence.IteratorMaker<Integer, Iterator<Integer>>() {

        @Override
        public Iterator<Integer> make() {
            return NUMS.iterator();
        }

        @Override
        public void cleanup(Iterator<Integer> iterFromMake) {
            // Do nothing.
        }
    }) {

        @Override
        public <OutType> Yielder<OutType> toYielder(final OutType initValue, final YieldingAccumulator<OutType, Integer> accumulator) {
            return super.toYielder(initValue, new DelegatingYieldingAccumulator<OutType, Integer>(accumulator) {

                @Override
                public OutType accumulate(OutType accumulated, Integer in) {
                    final OutType retVal = super.accumulate(accumulated, in);
                    yield();
                    return retVal;
                }
            });
        }
    };
