        throw new RuntimeException();
    });
    final AtomicBoolean effectExecuted = new AtomicBoolean();
    Sequence<Integer> seqWithEffect = throwingSeq.withEffect(() -> effectExecuted.set(true), Execs.directExecutor());
    try {
        seqWithEffect.toList();
        Assert.fail("expected RuntimeException");
    } catch (RuntimeException e) {
        // expected
        Assert.assertTrue(effectExecuted.get());
    }
}

