    final CloseTrackingCloseableIterator<Integer> actual = new CloseTrackingCloseableIterator<>(generateTestIterator(8).flatMap(list -> {
        CloseTrackingCloseableIterator<Integer> inner = new CloseTrackingCloseableIterator<>(CloseableIterators.withEmptyBaggage(list.iterator()));
