    Assert.assertEquals("foo", ((IdentifierExpr) decomposed.get(0)).getIdentifier());
}

@Test
public void test_decomposeAnd_basic() {
    final List<Expr> decomposed = Exprs.decomposeAnd(new BinAndExpr("&&", new BinAndExpr("&&", new IdentifierExpr("foo"), new IdentifierExpr("bar")), new BinAndExpr("&&", new IdentifierExpr("baz"), new IdentifierExpr("qux"))));
    // Expr instances don't, in general, implement value-based equals and hashCode. So we need to verify each field.
    Assert.assertEquals(4, decomposed.size());
    for (Expr expr : decomposed) {
        Assert.assertThat(expr, CoreMatchers.instanceOf(IdentifierExpr.class));
    }
    final List<String> identifiers = decomposed.stream().map(expr -> ((IdentifierExpr) expr).getIdentifier()).collect(Collectors.toList());
    Assert.assertEquals(ImmutableList.of("foo", "bar", "baz", "qux"), identifiers);
}

