@Test
public void testApplyFunctions() {
    validateParser("map(() -> 1, x)", "(map ([] -> 1), [x])", ImmutableList.of("x"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("map((x) -> x + 1, x)", "(map ([x] -> (+ x 1)), [x])", ImmutableList.of("x"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("x + map((x) -> x + 1, y)", "(+ x (map ([x] -> (+ x 1)), [y]))", ImmutableList.of("x", "y"), ImmutableSet.of("x"), ImmutableSet.of("y"));
    validateParser("x + map((x) -> x + 1, x)", "(+ x (map ([x] -> (+ x 1)), [x]))", ImmutableList.of("x"), ImmutableSet.of("x"), ImmutableSet.of("x_0"));
    validateParser("map((x) -> concat(x, y), z)", "(map ([x] -> (concat [x, y])), [z])", ImmutableList.of("y", "z"), ImmutableSet.of("y"), ImmutableSet.of("z"));
    // 'y' is accumulator, and currently unknown
    validateParser("fold((x, acc) -> acc + x, x, y)", "(fold ([x, acc] -> (+ acc x)), [x, y])", ImmutableList.of("x", "y"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("fold((x, acc) -> acc + x, map((x) -> x + 1, x), y)", "(fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])", ImmutableList.of("x", "y"), ImmutableSet.of(), ImmutableSet.of("x"));
    validateParser("array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y))", "(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])", ImmutableList.of("x", "y", "z"), ImmutableSet.of(), ImmutableSet.of("x", "z"));
    validateParser("map(z -> z + 1, array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y)))", "(map ([z] -> (+ z 1)), [(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])])", ImmutableList.of("x", "y", "z"), ImmutableSet.of(), ImmutableSet.of("x", "z"));
    validateParser("array_append(map(z -> z + 1, array_append(z, fold((x, acc) -> acc + x, map((x) -> x + 1, x), y))), a)", "(array_append [(map ([z] -> (+ z 1)), [(array_append [z, (fold ([x, acc] -> (+ acc x)), [(map ([x] -> (+ x 1)), [x]), y])])]), a])", ImmutableList.of("x", "y", "a", "z"), ImmutableSet.of("a"), ImmutableSet.of("x", "z"));
    validateFlatten("map((x) -> x + 1, [1, 2, 3, 4])", "(map ([x] -> (+ x 1)), [[1, 2, 3, 4]])", "[2, 3, 4, 5]");
    validateFlatten("map((x) -> x + z, [1, 2, 3, 4])", "(map ([x] -> (+ x z)), [[1, 2, 3, 4]])", "(map ([x] -> (+ x z)), [[1, 2, 3, 4]])");
}

