@Test
public void testCacheKeyBuilder() {
    final Cacheable cacheable = () -> new byte[] { 10, 20 };
    final byte[] actual = new CacheKeyBuilder((byte) 10).appendBoolean(false).appendString("test").appendInt(10).appendLong(Long.MAX_VALUE).appendFloat(0.1f).appendDouble(2.3).appendByteArray(// test when an item is same with the separator
    CacheKeyBuilder.STRING_SEPARATOR).appendFloatArray(new float[] { 10.0f, 11.0f }).appendStrings(Lists.newArrayList("test1", "test2")).appendCacheable(cacheable).appendCacheable(null).appendCacheables(Lists.newArrayList(cacheable, null, cacheable)).build();
    final int expectedSize = // id
    1 + // bool
    1 + // 'test'
    4 + // 10
    Integer.BYTES + // Long.MAX_VALUE
    Long.BYTES + // 0.1f
    Float.BYTES + // 2.3
    Double.BYTES + // byte array
    CacheKeyBuilder.STRING_SEPARATOR.length + // 10.0f, 11.0f
    Float.BYTES * 2 + Integer.BYTES + 5 * 2 + // 'test1' 'test2'
    1 + // cacheable
    cacheable.getCacheKey().length + Integer.BYTES + // cacheable list
    4 + // type keys
    12;
    Assert.assertEquals(expectedSize, actual.length);
    final byte[] expected = ByteBuffer.allocate(expectedSize).put((byte) 10).put(CacheKeyBuilder.BOOLEAN_KEY).put((byte) 0).put(CacheKeyBuilder.STRING_KEY).put(StringUtils.toUtf8("test")).put(CacheKeyBuilder.INT_KEY).putInt(10).put(CacheKeyBuilder.LONG_KEY).putLong(Long.MAX_VALUE).put(CacheKeyBuilder.FLOAT_KEY).putFloat(0.1f).put(CacheKeyBuilder.DOUBLE_KEY).putDouble(2.3).put(CacheKeyBuilder.BYTE_ARRAY_KEY).put(CacheKeyBuilder.STRING_SEPARATOR).put(CacheKeyBuilder.FLOAT_ARRAY_KEY).putFloat(10.0f).putFloat(11.0f).put(CacheKeyBuilder.STRING_LIST_KEY).putInt(2).put(StringUtils.toUtf8("test1")).put(CacheKeyBuilder.STRING_SEPARATOR).put(StringUtils.toUtf8("test2")).put(CacheKeyBuilder.CACHEABLE_KEY).put(cacheable.getCacheKey()).put(CacheKeyBuilder.CACHEABLE_KEY).put(CacheKeyBuilder.CACHEABLE_LIST_KEY).putInt(3).put(cacheable.getCacheKey()).put(cacheable.getCacheKey()).array();
    Assert.assertArrayEquals(expected, actual);
}

