@Test
public void testVersionedIntervalTimelineBehaviorForNumberedShardSpec() {
    //core partition chunks
    PartitionChunk<OvershadowableString> chunk0 = new NumberedShardSpec(0, 2).createChunk(new OvershadowableString("0", 0));
    PartitionChunk<OvershadowableString> chunk1 = new NumberedShardSpec(1, 2).createChunk(new OvershadowableString("1", 1));
    //appended partition chunk
    PartitionChunk<OvershadowableString> chunk4 = new NumberedShardSpec(4, 2).createChunk(new OvershadowableString("4", 4));
    //incomplete partition sets
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk0), Collections.emptySet());
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk1), Collections.emptySet());
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk4), Collections.emptySet());
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk0, chunk4), Collections.emptySet());
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk1, chunk4), Collections.emptySet());
    //complete partition sets
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk1, chunk0), ImmutableSet.of(new OvershadowableString("0", 0), new OvershadowableString("1", 1)));
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk4, chunk1, chunk0), ImmutableSet.of(new OvershadowableString("0", 0), new OvershadowableString("1", 1), new OvershadowableString("4", 4)));
    // a partition set with 0 core partitions
    chunk0 = new NumberedShardSpec(0, 0).createChunk(new OvershadowableString("0", 0));
    chunk4 = new NumberedShardSpec(4, 0).createChunk(new OvershadowableString("4", 4));
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk0), ImmutableSet.of(new OvershadowableString("0", 0)));
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk4), ImmutableSet.of(new OvershadowableString("4", 4)));
    testVersionedIntervalTimelineBehaviorForNumberedShardSpec(ImmutableList.of(chunk4, chunk0), ImmutableSet.of(new OvershadowableString("0", 0), new OvershadowableString("4", 4)));
}

