    expectedOvershadowedChunks.add(chunk);
    manager.addChunk(chunk);
    chunk = newNonRootChunk(8, 11, 2, 1);
    manager.addChunk(chunk);
    chunk = newNonRootChunk(5, 11, 3, 1);
    manager.addChunk(chunk);
    chunk = newNonRootChunk(0, 12, 5, 1);
    manager.addChunk(chunk);
    List<AtomicUpdateGroup<OvershadowableInteger>> overshadowedGroups = manager.findOvershadowedBy(RootPartitionRange.of(2, 10), (short) 10, State.OVERSHADOWED);
    Assert.assertEquals(expectedOvershadowedChunks.stream().map(AtomicUpdateGroup::new).collect(Collectors.toList()), overshadowedGroups);
