@Test
public void testPush() throws Exception {
    // Create a mock segment on disk
    File tmp = tempFolder.newFile("version.bin");
    final byte[] data = new byte[] { 0x0, 0x0, 0x0, 0x1 };
    Files.write(data, tmp);
    final long size = data.length;
    DataSegment segmentToPush = new DataSegment("foo", Intervals.of("2015/2016"), "0", new HashMap<>(), new ArrayList<>(), new ArrayList<>(), NoneShardSpec.instance(), 0, size);
    GoogleDataSegmentPusher pusher = createMockBuilder(GoogleDataSegmentPusher.class).withConstructor(storage, googleAccountConfig).addMockedMethod("insert", File.class, String.class, String.class).createMock();
    final String storageDir = pusher.getStorageDir(segmentToPush, false);
    final String indexPath = PREFIX + "/" + storageDir + "/" + "index.zip";
    pusher.insert(EasyMock.anyObject(File.class), EasyMock.eq("application/zip"), EasyMock.eq(indexPath));
    EasyMock.expectLastCall();
    replayAll();
    DataSegment segment = pusher.push(tempFolder.getRoot(), segmentToPush, false);
    Assert.assertEquals(segmentToPush.getSize(), segment.getSize());
    Assert.assertEquals(segmentToPush, segment);
    Assert.assertEquals(ImmutableMap.of("type", GoogleStorageDruidModule.SCHEME, "bucket", BUCKET, "path", indexPath), segment.getLoadSpec());
    verifyAll();
}

