        for (ProducerRecord<byte[], byte[]> record : Iterables.limit(records, 5)) {
            kafkaProducer.send(record).get();
        }
        kafkaProducer.commitTransaction();
    }
    while (task1.getRunner().getStatus() != Status.PAUSED) {
        Thread.sleep(10);
    }
