@Test
public void getPartitionTimeLag() throws InterruptedException {
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID0), EasyMock.eq(ShardIteratorType.TRIM_HORIZON.toString()), EasyMock.or(EasyMock.matches("\\d+"), EasyMock.isNull()))).andReturn(getShardIteratorResult0).anyTimes();
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID0), EasyMock.eq(ShardIteratorType.AT_SEQUENCE_NUMBER.toString()), EasyMock.matches("\\d+"))).andReturn(getShardIteratorResult0).anyTimes();
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID0), EasyMock.eq(ShardIteratorType.AFTER_SEQUENCE_NUMBER.toString()), EasyMock.matches("\\d+"))).andReturn(getShardIteratorResult0).anyTimes();
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID1), EasyMock.eq(ShardIteratorType.TRIM_HORIZON.toString()), EasyMock.or(EasyMock.matches("\\d+"), EasyMock.isNull()))).andReturn(getShardIteratorResult1).anyTimes();
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID1), EasyMock.eq(ShardIteratorType.AT_SEQUENCE_NUMBER.toString()), EasyMock.matches("\\d+"))).andReturn(getShardIteratorResult1).anyTimes();
    EasyMock.expect(kinesis.getShardIterator(EasyMock.anyObject(), EasyMock.eq(SHARD_ID1), EasyMock.eq(ShardIteratorType.AFTER_SEQUENCE_NUMBER.toString()), EasyMock.matches("\\d+"))).andReturn(getShardIteratorResult1).anyTimes();
    EasyMock.expect(getShardIteratorResult0.getShardIterator()).andReturn(SHARD0_ITERATOR).anyTimes();
    EasyMock.expect(getShardIteratorResult1.getShardIterator()).andReturn(SHARD1_ITERATOR).anyTimes();
    EasyMock.expect(kinesis.getRecords(generateGetRecordsReq(SHARD0_ITERATOR, recordsPerFetch))).andReturn(getRecordsResult0).anyTimes();
    EasyMock.expect(kinesis.getRecords(generateGetRecordsReq(SHARD1_ITERATOR, recordsPerFetch))).andReturn(getRecordsResult1).anyTimes();
    EasyMock.expect(getRecordsResult0.getRecords()).andReturn(SHARD0_RECORDS).times(2);
    EasyMock.expect(getRecordsResult1.getRecords()).andReturn(SHARD1_RECORDS_EMPTY).times(2);
    EasyMock.expect(getRecordsResult0.getNextShardIterator()).andReturn(null).anyTimes();
    EasyMock.expect(getRecordsResult1.getNextShardIterator()).andReturn(null).anyTimes();
    EasyMock.expect(getRecordsResult0.getMillisBehindLatest()).andReturn(SHARD0_LAG_MILLIS).times(2);
    EasyMock.expect(getRecordsResult1.getMillisBehindLatest()).andReturn(SHARD1_LAG_MILLIS_EMPTY).once();
    replayAll();
    Set<StreamPartition<String>> partitions = ImmutableSet.of(StreamPartition.of(STREAM, SHARD_ID0), StreamPartition.of(STREAM, SHARD_ID1));
    recordSupplier = new KinesisRecordSupplier(kinesis, recordsPerFetch, 0, 2, true, 100, 5000, 5000, 60000, 100, true);
    recordSupplier.assign(partitions);
    recordSupplier.seekToEarliest(partitions);
    recordSupplier.start();
    for (int i = 0; i < 10 && recordSupplier.bufferSize() < 12; i++) {
        Thread.sleep(100);
    }
    Map<String, Long> timeLag = recordSupplier.getPartitionResourcesTimeLag();
    Assert.assertEquals(partitions, recordSupplier.getAssignment());
    Assert.assertEquals(SHARDS_LAG_MILLIS_EMPTY, timeLag);
    Map<String, String> offsets = ImmutableMap.of(SHARD_ID1, SHARD1_RECORDS.get(0).getSequenceNumber(), SHARD_ID0, SHARD0_RECORDS.get(0).getSequenceNumber());
    Map<String, Long> independentTimeLag = recordSupplier.getPartitionsTimeLag(STREAM, offsets);
    Assert.assertEquals(SHARDS_LAG_MILLIS_EMPTY, independentTimeLag);
    // Verify that kinesis apis are not called for custom sequence numbers
    for (String sequenceNum : Arrays.asList(NO_END_SEQUENCE_NUMBER, END_OF_SHARD_MARKER, EXPIRED_MARKER)) {
        offsets = ImmutableMap.of(SHARD_ID1, sequenceNum, SHARD_ID0, sequenceNum);
        Assert.assertEquals(Collections.emptyMap(), recordSupplier.getPartitionsTimeLag(STREAM, offsets));
    }
    verifyAll();
}

