@Test
public void havingIncompatiblePropertiesIsForbidden() {
    final String targetRowsPerSegment = DimensionBasedPartitionsSpec.TARGET_ROWS_PER_SEGMENT;
    final String targetPartitionSize = DimensionBasedPartitionsSpec.TARGET_PARTITION_SIZE;
    final String maxRowsPerSegment = PartitionsSpec.MAX_ROWS_PER_SEGMENT;
    final String numShards = HashedPartitionsSpec.NUM_SHARDS;
    Multimap<String, String> incompatiblePairs = ImmutableMultimap.<String, String>builder().put(targetRowsPerSegment, targetPartitionSize).put(targetRowsPerSegment, maxRowsPerSegment).put(targetRowsPerSegment, numShards).put(targetPartitionSize, maxRowsPerSegment).put(targetPartitionSize, numShards).put(maxRowsPerSegment, numShards).build();
    for (Map.Entry<String, String> test : incompatiblePairs.entries()) {
        String first = test.getKey();
        String second = test.getValue();
        String reasonPrefix = first + "/" + second;
        String json = "{" + "\"type\":\"hashed\"" + ",\"" + first + "\":100" + ",\"" + second + "\":100" + "}";
        try {
            jsonReadWriteRead(json);
            Assert.fail(reasonPrefix + " did not throw exception");
        } catch (RuntimeException e) {
            final String expectedMessage = StringUtils.format("At most one of [Property{name='%s', value=100}] or [Property{name='%s', value=100}] must be present", first, second);
            Assert.assertThat(reasonPrefix + " has wrong failure message", e.getMessage(), CoreMatchers.containsString(expectedMessage));
        }
    }
}

