@Test
public void preservesMinAndMaxWhenAssumeGroupedFalse() {
    // Create a small bloom filter so that it saturates quickly
    int smallBloomFilter = 1;
    double manyFalsePositiveBloomFilter = 0.5;
    int minBloomFilterBits = Long.SIZE;
    long timestamp = 0;
    List<String> dimensionValues = IntStream.range(0, minBloomFilterBits * 10).mapToObj(i -> StringUtils.format("%010d", i)).collect(Collectors.toCollection(ArrayList::new));
    List<String> rows = dimensionValues.stream().map(d -> ParallelIndexTestingFactory.createRow(timestamp, d)).collect(Collectors.toList());
    Joiner joiner = Joiner.on("\n");
    InputSource inlineInputSource = new InlineInputSource(joiner.join(// saturate bloom filter first
    joiner.join(rows.subList(1, rows.size())), rows.get(0), rows.get(rows.size() - 1)));
    ParallelIndexTuningConfig tuningConfig = new ParallelIndexTestingFactory.TuningConfigBuilder().partitionsSpec(new ParallelIndexTestingFactory.SingleDimensionPartitionsSpecBuilder().assumeGrouped(false).build()).build();
    DataSchema dataSchema = ParallelIndexTestingFactory.createDataSchema(ParallelIndexTestingFactory.INPUT_INTERVALS);
    PartialDimensionDistributionTaskBuilder taskBuilder = new PartialDimensionDistributionTaskBuilder().tuningConfig(tuningConfig).dataSchema(dataSchema).inputSource(inlineInputSource).dedupRowDimValueFilterSupplier(() -> new PartialDimensionDistributionTask.DedupInputRowFilter(dataSchema.getGranularitySpec().getQueryGranularity(), smallBloomFilter, manyFalsePositiveBloomFilter));
    DimensionDistributionReport report = runTask(taskBuilder);
    Assert.assertEquals(ParallelIndexTestingFactory.ID, report.getTaskId());
    Map<Interval, StringDistribution> intervalToDistribution = report.getIntervalToDistribution();
    StringDistribution distribution = Iterables.getOnlyElement(intervalToDistribution.values());
    Assert.assertNotNull(distribution);
    PartitionBoundaries partitions = distribution.getEvenPartitionsByMaxSize(1);
    // 2 = min + max
    Assert.assertEquals(minBloomFilterBits + 2, partitions.size());
    String minDimensionValue = dimensionValues.get(0);
    Assert.assertEquals(minDimensionValue, ((StringSketch) distribution).getMin());
    String maxDimensionValue = dimensionValues.get(dimensionValues.size() - 1);
    Assert.assertEquals(maxDimensionValue, ((StringSketch) distribution).getMax());
}

