    lockbox.add(task1);
    tryTimeChunkLock(TaskLockType.EXCLUSIVE, task1, Intervals.of("2017-01-01/2017-02-01"));
    tryTimeChunkLock(TaskLockType.EXCLUSIVE, task1, Intervals.of("2017-04-01/2017-05-01"));
    // Acquire locks for task2
