    tryTimeChunkLock(TaskLockType.EXCLUSIVE, task2, Intervals.of("2017-03-01/2017-04-01"));
    // Verify the locked intervals
    final Map<String, Integer> minTaskPriority = new HashMap<>();
    minTaskPriority.put(task1.getDataSource(), 10);
    minTaskPriority.put(task2.getDataSource(), 10);
    final Map<String, List<Interval>> lockedIntervals = lockbox.getLockedIntervals(minTaskPriority);
    Assert.assertEquals(2, lockedIntervals.size());
    Assert.assertEquals(Arrays.asList(Intervals.of("2017-01-01/2017-02-01"), Intervals.of("2017-04-01/2017-05-01")), lockedIntervals.get(task1.getDataSource()));
    Assert.assertEquals(Collections.singletonList(Intervals.of("2017-03-01/2017-04-01")), lockedIntervals.get(task2.getDataSource()));
}

