@Test
public void testBroadcastJoin() throws Exception {
    final Closer closer = Closer.create();
    try {
        closer.register(unloader(BROADCAST_JOIN_DATASOURCE));
        closer.register(() -> {
            // remove broadcast rule
            try {
                coordinatorClient.postLoadRules(BROADCAST_JOIN_DATASOURCE, ImmutableList.of());
            } catch (Exception ignored) {
            }
        });
        // prepare for broadcast by adding forever broadcast load rule
        coordinatorClient.postLoadRules(BROADCAST_JOIN_DATASOURCE, ImmutableList.of(new ForeverBroadcastDistributionRule()));
        // load the data
        String taskJson = replaceJoinTemplate(getResourceAsString(BROADCAST_JOIN_TASK), BROADCAST_JOIN_DATASOURCE);
        indexer.submitTask(taskJson);
        ITRetryUtil.retryUntilTrue(() -> coordinatorClient.areSegmentsLoaded(BROADCAST_JOIN_DATASOURCE), "broadcast segment load");
        // query metadata until druid schema is refreshed and datasource is available joinable
        ITRetryUtil.retryUntilTrue(() -> {
            try {
                queryHelper.testQueriesFromString(queryHelper.getQueryURL(config.getRouterUrl()), replaceJoinTemplate(getResourceAsString(BROADCAST_JOIN_METADATA_QUERIES_RESOURCE), BROADCAST_JOIN_DATASOURCE));
                return true;
            } catch (Exception ex) {
                LOG.error(ex, "SQL metadata not yet in expected state");
                return false;
            }
        }, "waiting for SQL metadata refresh");
        // now do some queries
        queryHelper.testQueriesFromString(queryHelper.getQueryURL(config.getRouterUrl()), replaceJoinTemplate(getResourceAsString(BROADCAST_JOIN_QUERIES_RESOURCE), BROADCAST_JOIN_DATASOURCE));
    } finally {
        closer.close();
        // query metadata until druid schema is refreshed and datasource is no longer available
        ITRetryUtil.retryUntilTrue(() -> {
            try {
                queryHelper.testQueriesFromString(queryHelper.getQueryURL(config.getRouterUrl()), replaceJoinTemplate(getResourceAsString(BROADCAST_JOIN_METADATA_QUERIES_AFTER_DROP_RESOURCE), BROADCAST_JOIN_DATASOURCE));
                return true;
            } catch (Exception ex) {
                LOG.error(ex, "SQL metadata not yet in expected state");
                return false;
            }
        }, "waiting for SQL metadata refresh");
    }
}

@Test
public void testJdbcMetadata() {
    for (String url : connections) {
        try (Connection connection = DriverManager.getConnection(url, connectionProperties)) {
            DatabaseMetaData metadata = connection.getMetaData();
            List<String> catalogs = new ArrayList<>();
            ResultSet catalogsMetadata = metadata.getCatalogs();
            while (catalogsMetadata.next()) {
                final String catalog = catalogsMetadata.getString(1);
                catalogs.add(catalog);
            }
            LOG.info("catalogs %s", catalogs);
            Assert.assertEquals(catalogs, ImmutableList.of("druid"));
            Set<String> schemas = new HashSet<>();
            ResultSet schemasMetadata = metadata.getSchemas("druid", null);
            while (schemasMetadata.next()) {
                final String schema = schemasMetadata.getString(1);
                schemas.add(schema);
            }
            LOG.info("'druid' catalog schemas %s", schemas);
            // maybe more schemas than this, but at least should have these
            Assert.assertTrue(schemas.containsAll(ImmutableList.of("INFORMATION_SCHEMA", "druid", "lookup", "sys")));
            Set<String> druidTables = new HashSet<>();
            ResultSet tablesMetadata = metadata.getTables("druid", "druid", null, null);
            while (tablesMetadata.next()) {
                final String table = tablesMetadata.getString(3);
                druidTables.add(table);
            }
            LOG.info("'druid' schema tables %s", druidTables);
            // maybe more tables than this, but at least should have these
            Assert.assertTrue(druidTables.containsAll(ImmutableList.of("twitterstream", "wikipedia", WIKIPEDIA_DATA_SOURCE)));
            Set<String> wikiColumns = new HashSet<>();
            ResultSet columnsMetadata = metadata.getColumns("druid", "druid", WIKIPEDIA_DATA_SOURCE, null);
            while (columnsMetadata.next()) {
                final String column = columnsMetadata.getString(4);
                wikiColumns.add(column);
            }
            LOG.info("'%s' columns %s", WIKIPEDIA_DATA_SOURCE, wikiColumns);
            // a lot more columns than this, but at least should have these
            Assert.assertTrue(wikiColumns.containsAll(ImmutableList.of("added", "city", "delta", "language")));
        } catch (SQLException throwables) {
            Assert.assertFalse(true, throwables.getMessage());
        }
    }
}

