@Test
public void testMerge() {
    List<Result<Object>> resultsBefore = Arrays.asList(new Result<>(DateTimes.of("2011-01-01"), 1L), new Result<>(DateTimes.of("2011-01-01"), 2L));
    Iterable<Result<Object>> expectedResults = Collections.singletonList(new Result<>(DateTimes.of("2011-01-01"), 3L));
    Iterable<Result<Object>> resultsAfter = CombiningIterable.create(resultsBefore, Comparator.comparing(Result::getTimestamp), (arg1, arg2) -> {
        if (arg1 == null) {
            return arg2;
        }
        if (arg2 == null) {
            return arg1;
        }
        return new Result<>(arg1.getTimestamp(), ((Long) arg1.getValue()).longValue() + ((Long) arg2.getValue()).longValue());
    });
    Iterator<Result<Object>> it1 = expectedResults.iterator();
    Iterator<Result<Object>> it2 = resultsAfter.iterator();
    while (it1.hasNext() && it2.hasNext()) {
        Result r1 = it1.next();
        Result r2 = it2.next();
        Assert.assertEquals(r1.getTimestamp(), r2.getTimestamp());
        Assert.assertEquals(r1.getValue(), r2.getValue());
    }
}

