@Test
public void testMergeAggregators() {
    Assert.assertNull(AggregatorFactory.mergeAggregators(null));
    Assert.assertNull(AggregatorFactory.mergeAggregators(ImmutableList.of()));
    List<AggregatorFactory[]> aggregatorsToBeMerged = new ArrayList<>();
    aggregatorsToBeMerged.add(null);
    Assert.assertNull(AggregatorFactory.mergeAggregators(aggregatorsToBeMerged));
    AggregatorFactory[] emptyAggFactory = new AggregatorFactory[0];
    aggregatorsToBeMerged.clear();
    aggregatorsToBeMerged.add(emptyAggFactory);
    Assert.assertArrayEquals(emptyAggFactory, AggregatorFactory.mergeAggregators(aggregatorsToBeMerged));
    aggregatorsToBeMerged.clear();
    aggregatorsToBeMerged.add(emptyAggFactory);
    aggregatorsToBeMerged.add(null);
    Assert.assertNull(AggregatorFactory.mergeAggregators(aggregatorsToBeMerged));
    aggregatorsToBeMerged.clear();
    AggregatorFactory[] af1 = new AggregatorFactory[] { new LongMaxAggregatorFactory("name", "fieldName1") };
    AggregatorFactory[] af2 = new AggregatorFactory[] { new LongMaxAggregatorFactory("name", "fieldName2") };
    Assert.assertArrayEquals(new AggregatorFactory[] { new LongMaxAggregatorFactory("name", "name") }, AggregatorFactory.mergeAggregators(ImmutableList.of(af1, af2)));
    aggregatorsToBeMerged.clear();
    af1 = new AggregatorFactory[] { new LongMaxAggregatorFactory("name", "fieldName1") };
    af2 = new AggregatorFactory[] { new DoubleMaxAggregatorFactory("name", "fieldName2") };
    Assert.assertNull(AggregatorFactory.mergeAggregators(ImmutableList.of(af1, af2)));
}

@Test
public void testPruneDependentPostAgg() {
    PostAggregator agg1 = new ArithmeticPostAggregator("abc", "+", Lists.newArrayList(new ConstantPostAggregator("1", 1L), new ConstantPostAggregator("2", 2L)));
    PostAggregator dependency1 = new ArithmeticPostAggregator("dep1", "+", Lists.newArrayList(new ConstantPostAggregator("1", 1L), new ConstantPostAggregator("4", 4L)));
    PostAggregator agg2 = new FieldAccessPostAggregator("def", "def");
    PostAggregator dependency2 = new FieldAccessPostAggregator("dep2", "dep2");
    PostAggregator aggregator = new ArithmeticPostAggregator("finalAgg", "+", Lists.newArrayList(new FieldAccessPostAggregator("dep1", "dep1"), new FieldAccessPostAggregator("dep2", "dep2")));
    List<PostAggregator> prunedAgg = AggregatorUtil.pruneDependentPostAgg(Lists.newArrayList(agg1, dependency1, agg2, dependency2, aggregator), aggregator.getName());
    Assert.assertEquals(Lists.newArrayList(dependency1, dependency2, aggregator), prunedAgg);
}

@Test
public void testOutOfOrderPruneDependentPostAgg() {
    PostAggregator agg1 = new ArithmeticPostAggregator("abc", "+", Lists.newArrayList(new ConstantPostAggregator("1", 1L), new ConstantPostAggregator("2", 2L)));
    PostAggregator dependency1 = new ArithmeticPostAggregator("dep1", "+", Lists.newArrayList(new ConstantPostAggregator("1", 1L), new ConstantPostAggregator("4", 4L)));
    PostAggregator agg2 = new FieldAccessPostAggregator("def", "def");
