, "some_other_column"), null, "''", "<STRING>[]", null, "concat(__acc, some_column, some_other_column)", "array_set_add(__acc, string_array_expr)", null, "array_to_string(o, ';')", new HumanReadableBytes(2048), TestExprMacroTable.INSTANCE), new ExpressionLambdaAggregatorFactory("double_array_expr_finalized", ImmutableSet.of("some_column", "some_other_column_expr"), null, "0.0", "<DOUBLE>[]", null, "__acc + some_column + some_other_column", "array_set_add(__acc, double_array)", null, "array_to_string(o, ';')", new HumanReadableBytes(2048), TestExprMacroTable.INSTANCE), new ExpressionLambdaAggregatorFactory("long_array_expr_finalized", ImmutableSet.of("some_column", "some_other_column"), null, "0", "<LONG>[]", null, "__acc + some_column + some_other_column", "array_set_add(__acc, long_array_expr)", null, "fold((x, acc) -> x + acc, o, 0)", new HumanReadableBytes(2048), TestExprMacroTable.INSTANCE)).postAggregators(new FieldAccessPostAggregator("string-array-expr-access", "string_array_expr_finalized"), new FinalizingFieldAccessPostAggregator("string-array-expr-finalize", "string_array_expr_finalized"), new FieldAccessPostAggregator("double-array-expr-access", "double_array_expr_finalized"), new FinalizingFieldAccessPostAggregator("double-array-expr-finalize", "double_array_expr_finalized"), new FieldAccessPostAggregator("long-array-expr-access", "long_array_expr_finalized"), new FinalizingFieldAccessPostAggregator("long-array-expr-finalize", "long_array_expr_finalized")).build();
    Assert.assertEquals(RowSignature.builder().addTimeColumn().add("string_expr", ValueType.STRING).add("double_expr", ValueType.DOUBLE).add("long_expr", ValueType.LONG).add("string_array_expr", ValueType.STRING_ARRAY).// type does not equal finalized type. (combining factory type does equal finalized type,
    // but this signature doesn't use combining factory)
    add("double_array_expr", null).// type does not equal finalized type. (combining factory type does equal finalized type,
    // but this signature doesn't use combining factory)
    add("long_array_expr", null).// string because fold type equals finalized type, even though merge type is array
    add("string_array_expr_finalized", ValueType.STRING).// type does not equal finalized type. (combining factory type does equal finalized type,
    // but this signature doesn't use combining factory)
    add("double_array_expr_finalized", null).// long because fold type equals finalized type, even though merge type is array
    add("long_array_expr_finalized", ValueType.LONG).// fold type is string
    add("string-array-expr-access", ValueType.STRING).// finalized type is string
    add("string-array-expr-finalize", ValueType.STRING).// double because fold type is double
    add("double-array-expr-access", ValueType.DOUBLE).// string because finalize type is string
    add("double-array-expr-finalize", ValueType.STRING).// long because fold type is long
    add("long-array-expr-access", ValueType.LONG).// finalized type is long
    add("long-array-expr-finalize", ValueType.LONG).build(), new TimeseriesQueryQueryToolChest().resultArraySignature(query));
}

