/**
 * Expect no batching to occur and limit to be applied
 */
@Test
public void testNonOrderedScan() {
    ScanQuery query = Druids.newScanQueryBuilder().limit(limit).order(ScanQuery.Order.NONE).dataSource("some datasource").batchSize(batchSize).intervals(QueryRunnerTestHelper.FULL_ON_INTERVAL_SPEC).resultFormat(RESULT_FORMAT).context(ImmutableMap.of(ScanQuery.CTX_KEY_OUTERMOST, false)).build();
    QueryPlus<ScanResultValue> queryPlus = QueryPlus.wrap(query);
    ScanQueryLimitRowIterator itr = new ScanQueryLimitRowIterator(((queryInput, responseContext) -> Sequences.simple(multiEventScanResultValues)), queryPlus, ResponseContext.createEmpty());
    int count = 0;
    int expectedNumRows = Math.min(limit, NUM_ELEMENTS);
    while (itr.hasNext()) {
        ScanResultValue curr = itr.next();
        List<Map<String, Object>> events = ScanQueryTestHelper.getEventsListResultFormat(curr);
        if (events.size() != batchSize) {
            if (expectedNumRows - count > batchSize) {
                Assert.fail("Batch size is incorrect");
            } else {
                Assert.assertEquals(expectedNumRows - count, events.size());
            }
        }
        count += events.size();
    }
    Assert.assertEquals(expectedNumRows, count);
}

