@Test
public void testTimeseriesGrandTotal() {
    TimeseriesQuery query = Druids.newTimeseriesQueryBuilder().dataSource(QueryRunnerTestHelper.DATA_SOURCE).granularity(QueryRunnerTestHelper.DAY_GRAN).intervals(QueryRunnerTestHelper.FIRST_TO_THIRD).aggregators(Arrays.asList(QueryRunnerTestHelper.ROWS_COUNT, QueryRunnerTestHelper.INDEX_LONG_SUM, QueryRunnerTestHelper.QUALITY_UNIQUES, QueryRunnerTestHelper.INDEX_LONG_MIN, QueryRunnerTestHelper.INDEX_DOUBLE_MAX, QueryRunnerTestHelper.INDEX_FLOAT_MIN)).postAggregators(QueryRunnerTestHelper.ADD_ROWS_INDEX_CONSTANT).descending(descending).context(ImmutableMap.of(TimeseriesQuery.CTX_GRAND_TOTAL, true)).build();
    List<Result<TimeseriesResultValue>> expectedResults = new ArrayList<>();
    ImmutableMap.Builder<String, Object> builder = ImmutableMap.builder();
    expectedResults.add(new Result<>(DateTimes.of("2011-04-01"), new TimeseriesResultValue(builder.put("rows", 13L).put("index", 6619L).put("uniques", QueryRunnerTestHelper.UNIQUES_9).put(QueryRunnerTestHelper.ADD_ROWS_INDEX_CONSTANT_METRIC, 6633.0).put(QueryRunnerTestHelper.LONG_MIN_INDEX_METRIC, 78L).put(QueryRunnerTestHelper.DOUBLE_MAX_INDEX_METRIC, 1522.043733D).put(QueryRunnerTestHelper.FLOAT_MIN_INDEX_METRIC, 78.62254333496094F).build())));
    ImmutableMap.Builder<String, Object> builder2 = ImmutableMap.builder();
    expectedResults.add(new Result<>(DateTimes.of("2011-04-02"), new TimeseriesResultValue(builder2.put("rows", 13L).put("index", 5827L).put("uniques", QueryRunnerTestHelper.UNIQUES_9).put(QueryRunnerTestHelper.ADD_ROWS_INDEX_CONSTANT_METRIC, 5841.0).put(QueryRunnerTestHelper.LONG_MIN_INDEX_METRIC, 97L).put(QueryRunnerTestHelper.DOUBLE_MAX_INDEX_METRIC, 1321.375057D).put(QueryRunnerTestHelper.FLOAT_MIN_INDEX_METRIC, 97.38743591308594F).build())));
    if (descending) {
        Collections.reverse(expectedResults);
    }
    ImmutableMap.Builder<String, Object> builder3 = ImmutableMap.builder();
    expectedResults.add(new Result<>(null, new TimeseriesResultValue(builder3.put("rows", 26L).put("index", 12446L).put("uniques", QueryRunnerTestHelper.UNIQUES_9).put(QueryRunnerTestHelper.ADD_ROWS_INDEX_CONSTANT_METRIC, 12473.0).put(QueryRunnerTestHelper.LONG_MIN_INDEX_METRIC, 78L).put(QueryRunnerTestHelper.DOUBLE_MAX_INDEX_METRIC, 1522.043733D).put(QueryRunnerTestHelper.FLOAT_MIN_INDEX_METRIC, 78.62254333496094F).build())));
    // Must create a toolChest so we can run mergeResults (which applies grand totals).
    QueryToolChest<Result<TimeseriesResultValue>, TimeseriesQuery> toolChest = new TimeseriesQueryQueryToolChest();
    // Must wrapped in a results finalizer to stop the runner's builtin finalizer from being called.
    final FinalizeResultsQueryRunner finalRunner = new FinalizeResultsQueryRunner(toolChest.mergeResults(runner), toolChest);
