@Test
public void testFullOnTopNWithAggsOnNumericDims() {
    List<Pair<AggregatorFactory, List<?>>> aggregations = new ArrayList<>();
    aggregations.add(new Pair<>(QueryRunnerTestHelper.ROWS_COUNT, Longs.asList(186L, 186L, 837L)));
    Pair<AggregatorFactory, List<?>> indexAggregation = new Pair<>(QueryRunnerTestHelper.INDEX_DOUBLE_SUM, Doubles.asList(215679.82879638672D, 192046.1060180664D, 95606.57232284546D));
    aggregations.add(indexAggregation);
    aggregations.add(new Pair<>(QueryRunnerTestHelper.QUALITY_UNIQUES, Doubles.asList(QueryRunnerTestHelper.UNIQUES_2, QueryRunnerTestHelper.UNIQUES_2, QueryRunnerTestHelper.UNIQUES_9)));
    aggregations.add(new Pair<>(new DoubleMaxAggregatorFactory("maxIndex", "index"), Doubles.asList(1743.92175D, 1870.061029D, 277.273533D)));
    aggregations.add(new Pair<>(new DoubleMinAggregatorFactory("minIndex", "index"), Doubles.asList(792.3260498046875D, 545.9906005859375D, 59.02102279663086D)));
    aggregations.add(new Pair<>(new LongSumAggregatorFactory("qlLong", "qualityLong"), Longs.asList(279000L, 279000L, 1171800L)));
    aggregations.add(new Pair<>(new DoubleSumAggregatorFactory("qlFloat", "qualityLong"), Doubles.asList(279000.0, 279000.0, 1171800.0)));
    aggregations.add(new Pair<>(new DoubleSumAggregatorFactory("qfFloat", "qualityFloat"), Doubles.asList(2790000.0, 2790000.0, 11718000.0)));
    aggregations.add(new Pair<>(new LongSumAggregatorFactory("qfLong", "qualityFloat"), Longs.asList(2790000L, 2790000L, 11718000L)));
    List<List<Pair<AggregatorFactory, List<?>>>> aggregationCombinations = new ArrayList<>();
    for (Pair<AggregatorFactory, List<?>> aggregation : aggregations) {
        aggregationCombinations.add(Collections.singletonList(aggregation));
    }
    aggregationCombinations.add(aggregations);
    for (List<Pair<AggregatorFactory, List<?>>> aggregationCombination : aggregationCombinations) {
        boolean hasIndexAggregator = aggregationCombination.stream().anyMatch(agg -> "index".equals(agg.lhs.getName()));
        boolean hasRowsAggregator = aggregationCombination.stream().anyMatch(agg -> "rows".equals(agg.lhs.getName()));
        TopNQueryBuilder queryBuilder = new TopNQueryBuilder().dataSource(QueryRunnerTestHelper.DATA_SOURCE).granularity(QueryRunnerTestHelper.ALL_GRAN).dimension(QueryRunnerTestHelper.MARKET_DIMENSION).threshold(4).intervals(QueryRunnerTestHelper.FULL_ON_INTERVAL_SPEC).aggregators(aggregationCombination.stream().map(agg -> agg.lhs).collect(Collectors.toList()));
        String metric;
        if (hasIndexAggregator) {
            metric = "index";
        } else {
            metric = aggregationCombination.get(0).lhs.getName();
        }
        queryBuilder.metric(metric);
        if (hasIndexAggregator && hasRowsAggregator) {
            queryBuilder.postAggregators(QueryRunnerTestHelper.ADD_ROWS_INDEX_CONSTANT);
        }
        TopNQuery query = queryBuilder.build();
        ImmutableMap.Builder<String, Object> row1 = ImmutableMap.<String, Object>builder().put(QueryRunnerTestHelper.MARKET_DIMENSION, "total_market");
        ImmutableMap.Builder<String, Object> row2 = ImmutableMap.<String, Object>builder().put(QueryRunnerTestHelper.MARKET_DIMENSION, "upfront");
        ImmutableMap.Builder<String, Object> row3 = ImmutableMap.<String, Object>builder().put(QueryRunnerTestHelper.MARKET_DIMENSION, "spot");
        if (hasIndexAggregator && hasRowsAggregator) {
            row1.put("addRowsIndexConstant", 215866.82879638672D);
            row2.put("addRowsIndexConstant", 192233.1060180664D);
            row3.put("addRowsIndexConstant", 96444.57232284546D);
        }
        aggregationCombination.forEach(agg -> {
            row1.put(agg.lhs.getName(), agg.rhs.get(0));
            row2.put(agg.lhs.getName(), agg.rhs.get(1));
            row3.put(agg.lhs.getName(), agg.rhs.get(2));
        });
        List<ImmutableMap<String, Object>> rows = Lists.newArrayList(row1.build(), row2.build(), row3.build());
        rows.sort((r1, r2) -> ((Comparable) r2.get(metric)).compareTo(r1.get(metric)));
        List<Result<TopNResultValue>> expectedResults = Collections.singletonList(new Result<>(DateTimes.of("2011-01-12T00:00:00.000Z"), new TopNResultValue(rows)));
        assertExpectedResults(expectedResults, query);
    }
}

