    Assert.assertEquals(5, rowIngestionMeters.getUnparseable());
    Assert.assertEquals(maxSavedParseExceptions, parseExceptionHandler.getSavedParseExceptions().size());
    for (int i = 0; i < maxSavedParseExceptions; i++) {
