    Assert.assertFalse(inferred.hasMultipleValues().isMaybeTrue());
    Assert.assertTrue(inferred.hasBitmapIndexes());
    Assert.assertFalse(inferred.hasSpatialIndexes());
    // multiple input columns
    thePlan = plan("concat(scalar_dictionary_string, scalar_dictionary_string_nonunique)");
    Assert.assertTrue(thePlan.is(ExpressionPlan.Trait.VECTORIZABLE));
    Assert.assertFalse(thePlan.is(ExpressionPlan.Trait.SINGLE_INPUT_SCALAR, ExpressionPlan.Trait.SINGLE_INPUT_MAPPABLE, ExpressionPlan.Trait.INCOMPLETE_INPUTS, ExpressionPlan.Trait.UNKNOWN_INPUTS, ExpressionPlan.Trait.NEEDS_APPLIED, ExpressionPlan.Trait.NON_SCALAR_INPUTS, ExpressionPlan.Trait.NON_SCALAR_OUTPUT));
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedExpression().stringify());
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedFoldExpression("__acc").stringify());
    // what if scalar_dictionary_string_nonunique is an accumulator instead? nope, still no NEEDS_APPLIED so nothing to do
    Assert.assertEquals("concat(\"scalar_dictionary_string\", \"scalar_dictionary_string_nonunique\")", thePlan.getAppliedFoldExpression("scalar_dictionary_string_nonunique").stringify());
    Assert.assertEquals(ExprType.STRING, thePlan.getOutputType());
