@Test
public void testSimpleIngestion() throws Exception {
    try (final BatchAppenderatorTester tester = new BatchAppenderatorTester(3, true)) {
        final Appenderator appenderator = tester.getAppenderator();
        // startJob
        Assert.assertNull(appenderator.startJob());
        // getDataSource
        Assert.assertEquals(BatchAppenderatorTester.DATASOURCE, appenderator.getDataSource());
        // add #1
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(0), createInputRow("2000", "foo", 1), null).getNumRowsInSegment());
        // add #2
        Assert.assertEquals(1, appenderator.add(IDENTIFIERS.get(1), createInputRow("2000", "bar", 2), null).getNumRowsInSegment());
        // getSegments
        Assert.assertEquals(IDENTIFIERS.subList(0, 2), appenderator.getSegments().stream().sorted().collect(Collectors.toList()));
        // add #3, this hits max rows in memory:
        Assert.assertEquals(2, appenderator.add(IDENTIFIERS.get(1), createInputRow("2000", "sux", 1), null).getNumRowsInSegment());
        // since we just added three rows and the max rows in memory is three, all the segments (sinks etc)
        // above should be cleared now
