    EasyMock.expect(strategy.pickSegmentsToMove(EasyMock.anyObject(), EasyMock.anyObject(), EasyMock.anyInt(), EasyMock.anyInt())).andReturn(ImmutableList.of(new BalancerSegmentHolder(druidServer1, segment1), new BalancerSegmentHolder(druidServer1, segment2)).iterator());
    EasyMock.expect(strategy.findNewSegmentHomeBalancer(EasyMock.anyObject(), EasyMock.anyObject())).andReturn(new ServerHolder(druidServer3, peon3)).anyTimes();
    EasyMock.replay(strategy);
    DruidCoordinatorRuntimeParams params = defaultRuntimeParamsBuilder(ImmutableList.of(druidServer1, druidServer2, druidServer3), ImmutableList.of(peon1, peon2, peon3), ImmutableList.of(false, true, false)).withDynamicConfigs(CoordinatorDynamicConfig.builder().withMaxSegmentsToMove(3).withDecommissioningMaxPercentOfMaxSegmentsToMove(60).// ceil(3 * 0.6) = 2 segments from decommissioning servers
