    expectedRemainingSegments -= 40;
    assertCompactSegments(compactSegments, Intervals.of("2017-01-%02dT12:00:00/2017-01-%02dT00:00:00", 8, 9), expectedRemainingSegments, expectedCompactTaskCount, expectedVersionSupplier);
