@Test(timeout = 60_000L)
public void testSimple() throws Exception {
    LimitRequestsFilter filter = new LimitRequestsFilter(2);
    CountDownLatch latch1 = createAndStartRequestThread(filter, EasyMock.createStrictMock(ServletRequest.class), EasyMock.createStrictMock(HttpServletResponse.class));
    CountDownLatch latch2 = createAndStartRequestThread(filter, EasyMock.createStrictMock(ServletRequest.class), EasyMock.createStrictMock(HttpServletResponse.class));
    while (filter.getActiveRequestsCount() != 2) {
        Thread.sleep(100);
    }
    //now further requests should fail
    HttpServletResponse resp = EasyMock.createMock(HttpServletResponse.class);
    resp.sendError(429, "Too Many Requests");
    EasyMock.expectLastCall().times(2);
    EasyMock.replay(resp);
    filter.doFilter(EasyMock.createStrictMock(ServletRequest.class), resp, EasyMock.createStrictMock(FilterChain.class));
    filter.doFilter(EasyMock.createStrictMock(ServletRequest.class), resp, EasyMock.createStrictMock(FilterChain.class));
    EasyMock.verify(resp);
    //release one of the pending requests
    latch1.countDown();
    while (filter.getActiveRequestsCount() != 1) {
        Thread.sleep(100);
    }
    //now requests should go through
    FilterChain chain = EasyMock.createMock(FilterChain.class);
    chain.doFilter(EasyMock.anyObject(), EasyMock.anyObject());
    EasyMock.expectLastCall().times(2);
    EasyMock.replay(chain);
    filter.doFilter(EasyMock.createStrictMock(ServletRequest.class), EasyMock.createStrictMock(HttpServletResponse.class), chain);
    filter.doFilter(EasyMock.createStrictMock(ServletRequest.class), EasyMock.createStrictMock(HttpServletResponse.class), chain);
    EasyMock.verify(chain);
    latch2.countDown();
    while (filter.getActiveRequestsCount() != 0) {
        Thread.sleep(100);
    }
}

