@Test
public void testLoadDuplicatedSegmentsInParallel() throws ExecutionException, InterruptedException, SegmentLoadingException {
    final List<Future<Boolean>> futures = ImmutableList.of(SEGMENTS.get(0), SEGMENTS.get(0), SEGMENTS.get(0)).stream().map(segment -> executor.submit(() -> segmentManager.loadSegment(segment, false, SegmentLazyLoadFailCallback.NOOP))).collect(Collectors.toList());
    int numSucceededFutures = 0;
    int numFailedFutures = 0;
    for (Future<Boolean> future : futures) {
        numSucceededFutures += future.get() ? 1 : 0;
        numFailedFutures += future.get() ? 0 : 1;
    }
    Assert.assertEquals(1, numSucceededFutures);
    Assert.assertEquals(2, numFailedFutures);
    assertResult(ImmutableList.of(SEGMENTS.get(0)));
}

