public void testArrayStuffs() throws Exception {
    PreparedStatement statement = client.prepareStatement("SELECT ARRAY_AGG(dim2) AS arr1, ARRAY_AGG(l1) AS arr2, ARRAY_AGG(d1)  AS arr3, ARRAY_AGG(f1) AS arr4 FROM druid.numfoo");
