@Test
public void testUnplannableQueries() {
    // All of these queries are unplannable because they rely on features Druid doesn't support.
    // This test is here to confirm that we don't fall back to Calcite's interpreter or enumerable implementation.
    // It's also here so when we do support these features, we can have "real" tests for these queries.
    final List<String> queries = ImmutableList.of(// SELECT query with order by non-__time.
    "SELECT dim1 FROM druid.foo ORDER BY dim1", // JOIN condition with not-equals (<>).
    "SELECT foo.dim1, foo.dim2, l.k, l.v\n" + "FROM foo INNER JOIN lookup.lookyloo l ON foo.dim2 <> l.k", // JOIN condition with a function of both sides.
    "SELECT foo.dim1, foo.dim2, l.k, l.v\n" + "FROM foo INNER JOIN lookup.lookyloo l ON CHARACTER_LENGTH(foo.dim2 || l.k) > 3\n");
    for (final String query : queries) {
        assertQueryIsUnplannable(query);
    }
}

