@Test
public void testRegexpExtract() {
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("x(.)"), testHelper.makeLiteral(1)), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("x(.)", 1, true, null)), "regexp_extract(\"s\",'x(.)',1)"), null);
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("(o)"), testHelper.makeLiteral(1)), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("(o)", 1, true, null)), "regexp_extract(\"s\",'(o)',1)"), // Column "s" contains an 'o', but not at the beginning; we do match this.
    "o");
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeCall(SqlStdOperatorTable.CONCAT, testHelper.makeLiteral("Z"), testHelper.makeInputRef("s")), testHelper.makeLiteral("Zf(.)")), DruidExpression.fromExpression("regexp_extract(concat('Z',\"s\"),'Zf(.)')"), "Zfo");
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("f(.)"), testHelper.makeLiteral(1)), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("f(.)", 1, true, null)), "regexp_extract(\"s\",'f(.)',1)"), "o");
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("f(.)")), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("f(.)", 0, true, null)), "regexp_extract(\"s\",'f(.)')"), "fo");
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("")), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("", 0, true, null)), "regexp_extract(\"s\",'')"), NullHandling.emptyToNullIfNeeded(""));
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("")), DruidExpression.of(SimpleExtraction.of("s", new RegexDimExtractionFn("", 0, true, null)), "regexp_extract(\"s\",'')"), NullHandling.emptyToNullIfNeeded(""));
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("(.)")), DruidExpression.fromExpression("regexp_extract(null,'(.)')"), null);
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("")), DruidExpression.fromExpression("regexp_extract(null,'')"), null);
    testHelper.testExpression(new RegexpExtractOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("null")), DruidExpression.fromExpression("regexp_extract(null,'null')"), null);
}

@Test
public void testRegexpLike() {
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("f.")), DruidExpression.fromExpression("regexp_like(\"s\",'f.')"), 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("o")), DruidExpression.fromExpression("regexp_like(\"s\",'o')"), // Column "s" contains an 'o', but not at the beginning; we do match this.
    1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("x.")), DruidExpression.fromExpression("regexp_like(\"s\",'x.')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("s"), testHelper.makeLiteral("")), DruidExpression.fromExpression("regexp_like(\"s\",'')"), 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeLiteral("beep\nboop"), testHelper.makeLiteral("^beep$")), DruidExpression.fromExpression("regexp_like('beep\\u000Aboop','^beep$')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeLiteral("beep\nboop"), testHelper.makeLiteral("^beep\\nboop$")), DruidExpression.fromExpression("regexp_like('beep\\u000Aboop','^beep\\u005Cnboop$')"), 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("newliney"), testHelper.makeLiteral("^beep$")), DruidExpression.fromExpression("regexp_like(\"newliney\",'^beep$')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("newliney"), testHelper.makeLiteral("^beep\\nboop$")), DruidExpression.fromExpression("regexp_like(\"newliney\",'^beep\\u005Cnboop$')"), 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("newliney"), testHelper.makeLiteral("boo")), DruidExpression.fromExpression("regexp_like(\"newliney\",'boo')"), 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeInputRef("newliney"), testHelper.makeLiteral("^boo")), DruidExpression.fromExpression("regexp_like(\"newliney\",'^boo')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeCall(SqlStdOperatorTable.CONCAT, testHelper.makeLiteral("Z"), testHelper.makeInputRef("s")), testHelper.makeLiteral("x(.)")), DruidExpression.fromExpression("regexp_like(concat('Z',\"s\"),'x(.)')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("(.)")), DruidExpression.fromExpression("regexp_like(null,'(.)')"), 0L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("")), DruidExpression.fromExpression("regexp_like(null,'')"), // In SQL-compatible mode, nulls don't match anything. Otherwise, they match like empty strings.
    NullHandling.sqlCompatible() ? 0L : 1L);
    testHelper.testExpression(new RegexpLikeOperatorConversion().calciteOperator(), ImmutableList.of(testHelper.makeNullLiteral(SqlTypeName.VARCHAR), testHelper.makeLiteral("null")), DruidExpression.fromExpression("regexp_like(null,'null')"), 0L);
}

