    testHelper.testExpression(ContainsOperatorConversion.caseSensitive().calciteOperator(), ImmutableList.of(testHelper.makeCall(SqlStdOperatorTable.CONCAT, testHelper.makeLiteral("what is"), testHelper.makeInputRef("spacey")), testHelper.makeLiteral("there")), DruidExpression.fromExpression("contains_string(concat('what is',\"spacey\"),'there')"), 1L);
    testHelper.testExpression(ContainsOperatorConversion.caseInsensitive().calciteOperator(), ImmutableList.of(testHelper.makeCall(SqlStdOperatorTable.CONCAT, testHelper.makeLiteral("what is"), testHelper.makeInputRef("spacey")), testHelper.makeLiteral("There")), DruidExpression.fromExpression("icontains_string(concat('what is',\"spacey\"),'There')"), 1L);
    testHelper.testExpression(SqlStdOperatorTable.AND, ImmutableList.of(testHelper.makeCall(ContainsOperatorConversion.caseSensitive().calciteOperator(), testHelper.makeInputRef("spacey"), testHelper.makeLiteral("there")), testHelper.makeCall(SqlStdOperatorTable.EQUALS, testHelper.makeLiteral("yes"), testHelper.makeLiteral("yes"))), DruidExpression.fromExpression("(contains_string(\"spacey\",'there') && ('yes' == 'yes'))"), 1L);
    testHelper.testExpression(SqlStdOperatorTable.AND, ImmutableList.of(testHelper.makeCall(ContainsOperatorConversion.caseInsensitive().calciteOperator(), testHelper.makeInputRef("spacey"), testHelper.makeLiteral("There")), testHelper.makeCall(SqlStdOperatorTable.EQUALS, testHelper.makeLiteral("yes"), testHelper.makeLiteral("yes"))), DruidExpression.fromExpression("(icontains_string(\"spacey\",'There') && ('yes' == 'yes'))"), 1L);
